#!/usr/bin/env python3
import cadquery as cq
from pathlib import Path

SPEC = {'kind': 'extrusion', 'center': [-0.291993465, -0.045344465, 0.040262990000000005], 'basis': [[0.0, 0.9987361464580915, 0.05026041939778936], [-0.09995865537606774, -0.050008694687571874, 0.9937340678828788], [0.994991591530003, -0.0050239639416402564, 0.0998323222754263]], 'axis': [0.05026041939778936, 0.9937340678828788, 0.0998323222754263], 'zmin': -0.05032928516197383, 'zmax': 0.04791610536998336, 'profiles': [{'outer': [[-0.12318985294379457, -0.060235598384584824], [-0.11820989846108122, -0.028547624885575485], [-0.11748782579940427, -0.01853690535788913], [-0.11585254576764706, 0.008618173676567309], [-0.11633683615306525, 0.022169876195859917], [-0.11783696371332521, 0.03679515994183701], [-0.11787322171638977, 0.05364828050303244], [-0.11386250559065571, 0.07396087147573506], [-0.10675804489575785, 0.09345596425082223], [-0.09711146716530851, 0.10950483592547744], [-0.08513417221491662, 0.12205421277105735], [-0.0702952539402294, 0.12849545540450524], [-0.05467939897398964, 0.1320132410499107], [-0.04439013402880584, 0.13269913444453377], [-0.0418519953925091, 0.132538086627252], [-0.03841217971010781, 0.1321000498573648], [-0.03475128993377192, 0.131434951521631], [-0.031683944726330085, 0.13070743302371685], [-0.027855223952468228, 0.1300463527409699], [-0.01991359001842368, 0.12734309964762988], [-0.008692513329084547, 0.12388491820817121], [0.0035472915766549735, 0.11987423846082709], [0.012562310495366982, 0.11581991588640739], [0.023683610621012662, 0.11014107279617456], [0.03639825084454228, 0.10230416202090122], [0.055362239033484306, 0.08848603673893264], [0.06303008074906424, 0.08525818363159543], [0.07121868606547821, 0.0825478632281893], [0.07930910324959543, 0.08110828341546049], [0.08782236586211364, 0.07982702834141385], [0.10883909104606003, 0.07606399969063704], [0.12396001934725569, 0.06194324477553055], [0.12820166520950732, 0.03975172846334533], [0.12102375800966371, 0.0250838659150139], [0.1078236468418675, 0.013634119761438116], [0.10674640216406187, 0.013413560245870728], [0.09628429217303941, 0.014451108734891529], [0.08737953123794032, 0.015770936105363093], [0.06982756662700852, 0.022005841451759708], [0.06144308811887474, 0.024618906521068004], [0.053826806867567904, 0.026707940079631523], [0.04449650703522105, 0.027283676496567877], [0.04078058950439172, 0.02645694378266842], [0.038898358989683475, 0.02192474321482582], [0.03842421110778406, 0.011028315580565573], [0.03852215217880863, 0.002486079305697539], [0.0384703466524365, -0.006699991900666061], [0.03909892886588302, -0.028848546830948906], [0.04124932241658642, -0.04480639047321875], [0.04376603328748776, -0.06104778919065234], [0.04747400205596828, -0.08947995405571695], [0.046829890219872904, -0.10786128470469118], [0.04594718761990119, -0.11164250732393828], [0.036537928892500585, -0.12032808221076914], [0.024205372723173992, -0.12495432209646819], [0.009671354662242114, -0.12448988194766866], [0.005751432602549975, -0.12292325182976704], [-0.003738987711403702, -0.11826624019123136], [-0.008705076303358485, -0.0983773168167243], [-0.009730300242297773, -0.088260772535653], [-0.009699209148222117, -0.10101436673130237], [-0.011770025057782584, -0.10940525751928877], [-0.013262444368032065, -0.11865111769282315], [-0.025301197224116747, -0.12820313235931122], [-0.040351026189801416, -0.13283401472719972], [-0.055705056983848276, -0.12969783658543543], [-0.06826479065229142, -0.11971370850770742], [-0.07155511574889752, -0.10225249096522841], [-0.07127213242514913, -0.08865675629035594], [-0.07099778484882845, -0.08061263993864244], [-0.07272909008954498, -0.09737087577528995], [-0.07790029138205919, -0.11818658196428786], [-0.09145494648315171, -0.12530910034834647], [-0.10651540012581044, -0.12598641155148788], [-0.1187761297240717, -0.12045966585303589], [-0.12799495112887557, -0.11096339220478799], [-0.1274176922683459, -0.09018282377727047], [-0.12574437620552684, -0.08009180716676619]], 'holes': []}], 'simplify_tolerance': 5.31066298343467e-05, 'sketch_entity_count': 87}
OUT = Path(__file__).resolve().parent

def vec(v):
    return cq.Vector(float(v[0]), float(v[1]), float(v[2]))

def build():
    s = SPEC
    kind = s["kind"]
    B = s.get("basis")
    center = s.get("center")
    if kind == "extrusion":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = None
        height = s["zmax"] - s["zmin"]
        for profile in s["profiles"]:
            solid = cq.Workplane(plane).polyline(profile["outer"]).close().extrude(height)
            for hole in profile["holes"]:
                cutter = cq.Workplane(plane).polyline(hole).close().extrude(height)
                solid = solid.cut(cutter)
            result = solid if result is None else result.union(solid)
    elif kind == "multi_loft":
        def loft(track):
            wires = [cq.Wire.makePolygon([vec(p) for p in section], close=True) for section in track]
            return cq.Solid.makeLoft(wires, ruled=bool(s.get("ruled", True)))
        outer = [loft(track) for track in s["outer_tracks"]]
        # Keep disjoint solids as a legal STEP compound.  Global Boolean fusion
        # is unnecessary for training geometry and scales poorly with profiles.
        for track in s.get("hole_tracks", []):
            cutter = loft(track)
            cut_outer = []
            for solid in outer:
                try:
                    cut_outer.append(solid.cut(cutter))
                except Exception:
                    cut_outer.append(solid)
            outer = cut_outer
        result = outer[0] if len(outer) == 1 else cq.Compound.makeCompound(outer)
    elif kind == "box":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["mins"][0]*B[i][0] + s["mins"][1]*B[i][1] + s["mins"][2]*B[i][2] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        dx=s["maxs"][0]-s["mins"][0]; dy=s["maxs"][1]-s["mins"][1]; dz=s["maxs"][2]-s["mins"][2]
        result = cq.Workplane(plane).rect(dx,dy,centered=False).extrude(dz)
    elif kind == "cylinder":
        xdir = [B[i][0] for i in range(3)]
        axis = [B[i][2] for i in range(3)]
        origin = [center[i] + s["zmin"] * axis[i] for i in range(3)]
        plane = cq.Plane(origin=origin, xDir=xdir, normal=axis)
        result = cq.Workplane(plane).circle(s["radius"]).extrude(s["zmax"]-s["zmin"])
    else:
        raise ValueError(kind)
    cq.exporters.export(result, str(OUT / "reconstructed.step"))
    cq.exporters.export(result, str(OUT / "reconstructed.stl"), tolerance=0.001, angularTolerance=0.05)
    return result

if __name__ == "__main__":
    build()
